import json

def try_mirror_solution(grid):
    h, w = len(grid), len(grid[0])
    mirror_col = 4
    output = []
    for r in range(h):
        row = []
        for c in range(w):
            mirror_c = mirror_col - (c - mirror_col)
            # Mirror across col 4
            if c >= w - mirror_col and c <= mirror_col + mirror_col:
                row.append(3 if grid[r][c] == grid[r][mirror_c] else 5)
            else:
                row.append(5)
        output.append(row)
    return output

# Actually let me try a simpler approach: compare mirror positions
def try_simple_mirror(grid):
    h, w = len(grid), len(grid[0])
    # Find the central vertical axis (col 4 is all 8s)
    axis = 4
    output = [[5 for _ in range(w)] for _ in range(h)]
    # For cells in left half, check their mirror in right half
    for r in range(h):
        for c in range(w):
            # Find the symmetry partner
            # Mirror across col 4
            if c < axis:
                mirror = axis + (axis - c)  # e.g., c=3 mirrors to 5
            elif c > axis:
                mirror = axis - (c - axis)  # e.g., c=5 mirrors to 3
            else:
                mirror = c

            if grid[r][c] == grid[r][mirror]:
                output[r][c] = 3
            else:
                output[r][c] = 5
    return output

